cat > /workspace/project/src/roce_packet.c <<'EOF'
/* Offline RoCEv2 packet codec: strict ingress validation and canonical egress
 * sealing.  The rules implemented here are exactly those of PROTOCOL.md. */
#include "epic_clean.h"

#include <arpa/inet.h>
#include <stdlib.h>
#include <string.h>

#define ETHERTYPE_IPV4 0x0800
#define ROCE_OPCODE_DATA 0x04u
#define ROCE_OPCODE_ACK 0x11u

static uint32_t crc32_table[256];
static bool crc32_ready;

void epic_crc32_init(void) {
    if (crc32_ready) {
        return;
    }
    const uint32_t poly = 0xedb88320u;
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t crc = i;
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1u) ? poly : 0u);
        }
        crc32_table[i] = crc;
    }
    crc32_ready = true;
}

static uint32_t epic_crc32(const void *data, size_t len) {
    epic_crc32_init();
    const uint8_t *buf = data;
    uint32_t crc = 0xffffffffu;
    while (len--) {
        crc = (crc >> 8) ^ crc32_table[(crc ^ *buf++) & 0xffu];
    }
    return crc ^ 0xffffffffu;
}

uint16_t epic_ipv4_checksum(const void *data, size_t len) {
    const uint8_t *bytes = data;
    uint32_t sum = 0;
    while (len > 1) {
        sum += (uint16_t)((bytes[0] << 8) | bytes[1]);
        bytes += 2;
        len -= 2;
    }
    if (len) {
        sum += (uint16_t)(bytes[0] << 8);
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    return htons((uint16_t)~sum);
}

/* ICRC input: eight 0xff bytes followed by the IPv4 datagram without the
 * trailing ICRC, with TOS, TTL, IPv4 checksum, UDP checksum and the QPN top
 * byte masked to 0xff.  Result is the standard reflected CRC32. */
uint32_t epic_compute_icrc(const uint8_t *frame, size_t frame_len) {
    if (frame_len < EPIC_ETH_LEN + EPIC_IP_LEN + EPIC_ICRC_LEN) {
        return 0;
    }
    const epic_ipv4_t *ip = (const epic_ipv4_t *)(frame + EPIC_ETH_LEN);
    size_t ip_len = ntohs(ip->total_length);
    if (ip_len < EPIC_IP_LEN + EPIC_UDP_LEN + EPIC_BTH_LEN + EPIC_ICRC_LEN ||
        EPIC_ETH_LEN + ip_len != frame_len) {
        return 0;
    }
    uint8_t buf[EPIC_MAX_FRAME];
    size_t crc_len = 8 + ip_len - EPIC_ICRC_LEN;
    if (crc_len > sizeof(buf)) {
        return 0;
    }
    memset(buf, 0xff, 8);
    memcpy(buf + 8, frame + EPIC_ETH_LEN, ip_len - EPIC_ICRC_LEN);
    buf[8 + 1] = 0xff;                    /* IPv4 TOS */
    buf[8 + 8] = 0xff;                    /* IPv4 TTL */
    buf[8 + 10] = 0xff;                   /* IPv4 checksum */
    buf[8 + 11] = 0xff;
    buf[8 + 20 + 6] = 0xff;               /* UDP checksum */
    buf[8 + 20 + 7] = 0xff;
    buf[8 + 20 + 8 + 4] = 0xff;           /* BTH QPN top byte */
    return epic_crc32(buf, crc_len);
}

static uint16_t load16(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }
static uint32_t load24(const uint8_t *p) {
    return ((uint32_t)p[0] << 16) | ((uint32_t)p[1] << 8) | p[2];
}
static uint32_t load32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) |
           p[3];
}

bool epic_wire_validate(const uint8_t *frame, size_t frame_len, size_t words,
                        epic_wire_t *out) {
    const size_t ip_off = EPIC_ETH_LEN;
    const size_t udp_off = ip_off + EPIC_IP_LEN;
    const size_t bth_off = udp_off + EPIC_UDP_LEN;

    out->is_ack = false;
    out->psn = 0;
    out->qpn = 0;
    out->payload = NULL;
    out->payload_len = 0;

    if (!frame || !out) {
        return false;
    }
    /* Ethernet: IPv4 only, no FCS or padding is present. */
    if (frame_len < EPIC_ETH_LEN + EPIC_IP_LEN + EPIC_UDP_LEN + EPIC_BTH_LEN +
                       EPIC_ICRC_LEN) {
        return false;
    }
    if (load16(frame + 12) != ETHERTYPE_IPV4) {
        return false;
    }
    const uint8_t *ip = frame + ip_off;
    if (ip[0] != 0x45) {                      /* version 4, IHL 20, no options */
        return false;
    }
    size_t ip_len = load16(ip + 2);
    if (ip_len < EPIC_IP_LEN + EPIC_UDP_LEN + EPIC_BTH_LEN + EPIC_ICRC_LEN ||
        frame_len != EPIC_ETH_LEN + ip_len) { /* exact length agreement */
        return false;
    }
    if (ip[9] != 17) {                        /* protocol UDP */
        return false;
    }
    uint16_t flags = (uint16_t)((ip[6] << 8) | ip[7]);
    if (flags != 0x0000 && flags != 0x4000) { /* DF only, never fragmented */
        return false;
    }
    uint8_t hdr[EPIC_IP_LEN];
    memcpy(hdr, ip, EPIC_IP_LEN);
    hdr[10] = 0;
    hdr[11] = 0;
    if (load16(ip + 10) != epic_ipv4_checksum(hdr, EPIC_IP_LEN)) {
        return false;
    }
    const uint8_t *udp = ip + EPIC_IP_LEN;
    size_t udp_len = load16(udp + 4);
    if (udp_len != ip_len - EPIC_IP_LEN) {
        return false;
    }
    if (load16(udp + 0) != EPIC_ROCE_UDP_PORT ||
        load16(udp + 2) != EPIC_ROCE_UDP_PORT || load16(udp + 6) != 0) {
        return false;
    }
    if (udp_len < EPIC_UDP_LEN + EPIC_BTH_LEN + EPIC_ICRC_LEN) {
        return false;
    }
    const uint8_t *bth = udp + EPIC_UDP_LEN;
    uint8_t opcode = bth[0];
    if (opcode != ROCE_OPCODE_DATA && opcode != ROCE_OPCODE_ACK) {
        return false;
    }
    if (bth[1] != 0) { /* flags/padding byte zero */
        return false;
    }
    if (load16(bth + 2) != 0xffff) {
        return false;
    }
    uint32_t qpn = load32(bth + 4);
    if ((qpn >> 24) & 0xffu) {
        return false;
    }
    uint32_t apsn = load32(bth + 8);
    uint32_t psn = apsn & EPIC_PSN_MASK;
    if (opcode == ROCE_OPCODE_DATA) {
        if ((apsn >> 24) != 0x80u) {
            return false;
        }
    } else if ((apsn >> 24) != 0x00u) {
        return false;
    }
    size_t body_len = udp_len - EPIC_UDP_LEN - EPIC_BTH_LEN - EPIC_ICRC_LEN;
    if (opcode == ROCE_OPCODE_DATA) {
        if (body_len != 4u * words) {
            return false;
        }
        out->payload = bth + EPIC_BTH_LEN;
        out->payload_len = body_len;
    } else {
        if (body_len != EPIC_AETH_LEN) {
            return false;
        }
        uint32_t aeth = load32(bth + EPIC_BTH_LEN);
        if ((aeth >> 24) != 0x1fu || (aeth & EPIC_PSN_MASK) != ((psn + 1u) & EPIC_PSN_MASK)) {
            return false;
        }
        out->is_ack = true;
    }
    if (load32(frame + frame_len - EPIC_ICRC_LEN) != epic_compute_icrc(frame, frame_len)) {
        return false;
    }
    out->psn = psn;
    out->qpn = qpn & EPIC_PSN_MASK;
    return true;
}

static size_t build_base(uint8_t *frame, size_t frame_cap, int rank, uint32_t psn,
                         uint8_t opcode, size_t body_len) {
    size_t total = EPIC_DATA_HEAD + body_len + EPIC_ICRC_LEN;
    if (frame_cap < total || total > sizeof(((epic_eth_t *)0)) * 0 + EPIC_MAX_FRAME) {
        return 0;
    }
    memset(frame, 0, total);
    epic_eth_t *eth = (epic_eth_t *)frame;
    eth->dst_mac[0] = 0x02;
    eth->dst_mac[5] = (uint8_t)(rank + 1);
    eth->src_mac[0] = 0x02;
    eth->src_mac[1] = 0x01;
    eth->src_mac[5] = (uint8_t)(rank + 1);
    eth->ether_type = htons(ETHERTYPE_IPV4);

    epic_ipv4_t *ip = (epic_ipv4_t *)(frame + EPIC_ETH_LEN);
    ip->version_ihl = 0x45;
    ip->tos = 0;
    ip->total_length = htons((uint16_t)(total - EPIC_ETH_LEN));
    ip->id = htons(0x1111);
    ip->flags_frag_off = htons(0x4000);
    ip->ttl = 64;
    ip->protocol = 17;
    ip->src_ip = htonl(0x0a000065u + (uint32_t)rank);
    ip->dst_ip = htonl(0x0a000001u + (uint32_t)rank);
    ip->checksum = epic_ipv4_checksum(ip, EPIC_IP_LEN);

    epic_udp_t *udp = (epic_udp_t *)((uint8_t *)ip + EPIC_IP_LEN);
    udp->src_port = htons(EPIC_ROCE_UDP_PORT);
    udp->dst_port = htons(EPIC_ROCE_UDP_PORT);
    udp->length = htons((uint16_t)(total - EPIC_ETH_LEN - EPIC_IP_LEN));
    udp->checksum = 0;

    epic_bth_t *bth = (epic_bth_t *)((uint8_t *)udp + EPIC_UDP_LEN);
    bth->opcode = opcode;
    bth->se_m_pad = 0;
    bth->pkey = htons(0xffff);
    bth->qpn = htonl((uint32_t)(0x100 + rank) & EPIC_PSN_MASK);
    bth->apsn = htonl((psn & EPIC_PSN_MASK) |
                      (opcode == ROCE_OPCODE_DATA ? 0x80000000u : 0u));
    return total;
}

size_t epic_build_data(uint8_t *frame, size_t frame_cap, int rank, uint32_t psn,
                       const uint8_t *payload, size_t payload_bytes) {
    if (payload_bytes > EPIC_MAX_PAYLOAD_BYTES ||
        (payload_bytes > 0 && !payload) || payload_bytes % 4 != 0) {
        return 0;
    }
    size_t total = build_base(frame, frame_cap, rank, psn, ROCE_OPCODE_DATA,
                              payload_bytes);
    if (!total) {
        return 0;
    }
    if (payload_bytes) {
        memcpy(frame + EPIC_DATA_HEAD, payload, payload_bytes);
    }
    uint32_t icrc = htoepic_icrc(epic_compute_icrc(frame, total));
    memcpy(frame + total - EPIC_ICRC_LEN, &icrc, EPIC_ICRC_LEN);
    return total;
}

size_t epic_build_ack(uint8_t *frame, size_t frame_cap, int rank, uint32_t psn) {
    size_t total = build_base(frame, frame_cap, rank, psn, ROCE_OPCODE_ACK,
                              EPIC_AETH_LEN);
    if (!total) {
        return 0;
    }
    uint32_t aeth = htonl(0x1fu << 24 | ((psn + 1u) & EPIC_PSN_MASK));
    memcpy(frame + EPIC_DATA_HEAD, &aeth, EPIC_AETH_LEN);
    uint32_t icrc = htoepic_icrc(epic_compute_icrc(frame, total));
    memcpy(frame + total - EPIC_ICRC_LEN, &icrc, EPIC_ICRC_LEN);
    return total;
}
